create table xxventuri.xxeba_sales_brands (
    brand_id              number not null enable,
    entity_id             number,
    entity_type           varchar2(100 byte),
    brand_name            varchar2(100 byte),
    brand_code            varchar2(50 byte),
    brand_price           number,
    unit_of_measure       varchar2(50 byte),
    minimum_order_qty     number,
    lead_time             number,
    brand_currency_type   varchar2(50 byte),
    brand_attachment      blob,
    brand_att_mimetype    varchar2(255 byte),
    brand_att_filename    varchar2(255 byte),
    brand_att_charset     varchar2(128 byte),
    brand_att_last_update date,
    created_by            varchar2(255 byte),
    created               timestamp(6) with local time zone,
    updated_by            varchar2(255 byte),
    updated               timestamp(6) with local time zone
);


